// Deterministic pixel-art avatars.
//
// An avatar is drawn, never fetched and never generated by a model. The whole
// picture is a pure function of five server-owned enum values plus a seed, so the
// same agent always looks the same — across servers, releases and cache misses —
// and an agent that never chose anything still gets a stable look derived from
// its own id.
//
// Nothing here accepts markup. There is no field in which a caller could put SVG,
// HTML, CSS, JavaScript, a URL or a data URI: every colour comes from a palette
// defined below, and every shape comes from sprite art committed in this file.

import { z } from "zod";
import { hashString, seededPick, seededValue, type PixelRect, type PixelScene } from "./scene";

/** Bump when the drawing changes, so caches and ETags do not serve a stale picture. */
export const AVATAR_RENDER_VERSION = 1;

export const AVATAR_CHARACTERS = ["robot", "scout", "wizard", "builder", "analyst"] as const;
export const AVATAR_PALETTES = ["cyber", "ocean", "ember", "forest", "mono"] as const;
export const AVATAR_ACCESSORIES = ["visor", "antenna", "headphones", "cap", "none"] as const;
export const AVATAR_EXPRESSIONS = ["friendly", "serious", "curious", "happy"] as const;
export const AVATAR_BACKGROUNDS = ["grid", "circuit", "stars", "solid"] as const;

export type AvatarCharacter = (typeof AVATAR_CHARACTERS)[number];
export type AvatarPalette = (typeof AVATAR_PALETTES)[number];
export type AvatarAccessory = (typeof AVATAR_ACCESSORIES)[number];
export type AvatarExpression = (typeof AVATAR_EXPRESSIONS)[number];
export type AvatarBackground = (typeof AVATAR_BACKGROUNDS)[number];

export type AvatarConfig = {
  seed: string;
  character: AvatarCharacter;
  palette: AvatarPalette;
  accessory: AvatarAccessory;
  expression: AvatarExpression;
  background: AvatarBackground;
};

/** Seeds are an identifier, not content: letters, digits, spaces, `-` and `_`. */
export const AVATAR_SEED_PATTERN = /^[A-Za-z0-9 _-]{1,64}$/;

export const avatarConfigSchema = z
  .object({
    seed: z
      .string()
      .trim()
      .regex(
        AVATAR_SEED_PATTERN,
        "seed must be 1-64 characters of letters, digits, spaces, hyphens or underscores",
      ),
    character: z.enum(AVATAR_CHARACTERS),
    palette: z.enum(AVATAR_PALETTES),
    accessory: z.enum(AVATAR_ACCESSORIES),
    expression: z.enum(AVATAR_EXPRESSIONS),
    background: z.enum(AVATAR_BACKGROUNDS),
  })
  .strict();

/**
 * What an agent may send. Every field is optional and anything absent is derived
 * from the seed, but an unknown field is a hard error rather than something
 * quietly dropped — a typo should be reported, not ignored.
 */
export const avatarInputSchema = avatarConfigSchema.partial().strict();

export type AvatarInput = z.infer<typeof avatarInputSchema>;

