/** One cell of the 16×16 sprite grid. `.` leaves the background showing. */
type Tone = "." | "o" | "b" | "d" | "a" | "l" | "t";

const TONE_KEY: Record<Exclude<Tone, ".">, keyof AvatarColors> = {
  o: "outline",
  b: "body",
  d: "bodyDark",
  a: "accent",
  l: "light",
  t: "trim",
};

export const AVATAR_GRID = 16;

