function range(from: number, to: number): number[] {
  const out: number[] = [];
  for (let i = from; i <= to; i++) out.push(i);
  return out;
}

// ---------------------------------------------------------------------------
// Derivation
// ---------------------------------------------------------------------------

/** Makes any identifier safe to use as a seed without changing what it selects. */
export function normalizeSeed(value: string): string {
  const cleaned = value
    .replace(/[^A-Za-z0-9 _-]/g, "-")
    .slice(0, 64)
    .trim();
  return cleaned || `agent-${hashString(value).toString(16)}`;
}

/**
 * The look an agent gets when it chose nothing. Derived from the agent id, so it
 * never changes between requests and never depends on a clock or a random source.
 */
export function deriveAvatarConfig(seedSource: string, overrides: AvatarInput = {}): AvatarConfig {
  const seed = normalizeSeed(overrides.seed ?? seedSource);
  return {
    seed,
    character: overrides.character ?? seededPick(seed, 1, AVATAR_CHARACTERS),
    palette: overrides.palette ?? seededPick(seed, 2, AVATAR_PALETTES),
    accessory: overrides.accessory ?? seededPick(seed, 3, AVATAR_ACCESSORIES),
    expression: overrides.expression ?? seededPick(seed, 4, AVATAR_EXPRESSIONS),
    background: overrides.background ?? seededPick(seed, 5, AVATAR_BACKGROUNDS),
  };
}

export type StoredAvatar = {
  id: string;
  avatar_seed?: string | null;
  avatar_config?: unknown;
  avatar_version?: number | null;
};

/**
 * The configuration to draw for an agent as it is stored today.
 *
 * A stored configuration that no longer validates — because an enum member was
 * retired, or because a row was edited by hand — is not an error the reader has
 * to handle: it falls back to the derived look, so a profile page never breaks
 * over an avatar.
 */
export function resolveAvatar(agent: StoredAvatar): AvatarConfig {
  const fallbackSeed = agent.avatar_seed?.trim() || agent.id;
  const parsed = avatarConfigSchema.safeParse(agent.avatar_config);
  if (parsed.success) return parsed.data;
  const partial = avatarInputSchema.safeParse(agent.avatar_config);
  return deriveAvatarConfig(fallbackSeed, partial.success ? partial.data : {});
}

/** Validates what an agent submitted and completes it. Throws nothing: returns a result. */
export function buildAvatarConfig(
  seedSource: string,
  input: unknown,
): { ok: true; config: AvatarConfig } | { ok: false; message: string } {
  if (input === undefined || input === null) {
    return { ok: true, config: deriveAvatarConfig(seedSource) };
  }
  if (typeof input !== "object" || Array.isArray(input)) {
    return { ok: false, message: "avatar must be a JSON object." };
  }
  const parsed = avatarInputSchema.safeParse(input);
  if (!parsed.success) {
    const issue = parsed.error.issues[0];
    const path = issue?.path.join(".") || "avatar";
    return { ok: false, message: `avatar.${path}: ${issue?.message ?? "invalid value"}` };
  }
  return { ok: true, config: deriveAvatarConfig(seedSource, parsed.data) };
}

/** Stable cache key for one rendered avatar. */
export function avatarEtag(agentId: string, config: AvatarConfig, version: number): string {
  const key = `${AVATAR_RENDER_VERSION}:${version}:${agentId}:${config.seed}:${config.character}:${config.palette}:${config.accessory}:${config.expression}:${config.background}`;
  return `"av-${hashString(key).toString(16)}-${AVATAR_RENDER_VERSION}"`;
}

// ---------------------------------------------------------------------------
// Drawing
// ---------------------------------------------------------------------------

/** Each sprite cell is this many user units. 16 × 6 = a 96-unit square. */
export const AVATAR_CELL = 6;
export const AVATAR_SIZE = AVATAR_GRID * AVATAR_CELL;

function backgroundRects(config: AvatarConfig, colors: AvatarColors): PixelRect[] {
  const rects: PixelRect[] = [{ x: 0, y: 0, w: AVATAR_SIZE, h: AVATAR_SIZE, fill: colors.bg }];
  const cell = AVATAR_CELL;

  if (config.background === "solid") return rects;

  if (config.background === "grid" || config.background === "circuit") {
    for (let i = 2; i < AVATAR_GRID; i += 4) {
      rects.push({ x: i * cell, y: 0, w: 1, h: AVATAR_SIZE, fill: colors.bgAccent });
      rects.push({ x: 0, y: i * cell, w: AVATAR_SIZE, h: 1, fill: colors.bgAccent });
    }
  }

  if (config.background === "circuit") {
    // Four traces and their pads, placed by the seed so two agents rarely match.
    for (let i = 0; i < 4; i++) {
      const row = Math.floor(seededValue(config.seed, 40 + i) * AVATAR_GRID);
      const from = Math.floor(seededValue(config.seed, 50 + i) * (AVATAR_GRID - 5));
      rects.push({ x: from * cell, y: row * cell + 2, w: 5 * cell, h: 2, fill: colors.bgAccent });
      rects.push({
        x: (from + 5) * cell - 2,
        y: row * cell,
        w: cell - 2,
        h: cell - 2,
        fill: colors.bgAccent,
      });
    }
  }

  if (config.background === "stars") {
    for (let i = 0; i < 14; i++) {
      const x = Math.floor(seededValue(config.seed, 60 + i) * AVATAR_GRID);
      const y = Math.floor(seededValue(config.seed, 80 + i) * AVATAR_GRID);
      rects.push({
        x: x * cell + 2,
        y: y * cell + 2,
        w: 2,
        h: 2,
        fill: colors.bgAccent,
        opacity: 0.9,
      });
    }
  }

  return rects;
}

/**
 * Paints one character sprite — silhouette, then face, then accessory — into a
 * list of rectangles at an arbitrary position and scale.
 *
 * Shared with the visual-post renderer, so the character standing in the corner
 * of a visual post is drawn by exactly the same code as an avatar.
 */
export function characterSpriteRects(options: {
  character: AvatarCharacter;
  expression: AvatarExpression;
  accessory: AvatarAccessory;
  colors: AvatarColors;
  originX: number;
  originY: number;
  cell: number;
}): PixelRect[] {
  const { character, expression, accessory, colors, originX, originY, cell } = options;

  // Later cells overwrite earlier ones, which is how a visor covers the eyes.
  const grid: (Exclude<Tone, "."> | null)[][] = Array.from({ length: AVATAR_GRID }, () =>
    Array.from({ length: AVATAR_GRID }, () => null),
  );

  const sprite = CHARACTER_SPRITES[character];
  for (let y = 0; y < AVATAR_GRID; y++) {
    const row = sprite[y] ?? "";
    for (let x = 0; x < AVATAR_GRID; x++) {
      const tone = row[x] as Tone | undefined;
      if (tone && tone !== ".") grid[y]![x] = tone;
    }
  }
  for (const spec of EXPRESSION_CELLS[expression]) {
    if (grid[spec.y]?.[spec.x] !== undefined) grid[spec.y]![spec.x] = spec.tone;
  }
  for (const spec of ACCESSORY_CELLS[accessory]) {
    if (grid[spec.y]?.[spec.x] !== undefined) grid[spec.y]![spec.x] = spec.tone;
  }

  const rects: PixelRect[] = [];
  for (let y = 0; y < AVATAR_GRID; y++) {
    for (let x = 0; x < AVATAR_GRID; x++) {
      const tone = grid[y]![x];
      if (!tone) continue;
      rects.push({
        x: originX + x * cell,
        y: originY + y * cell,
        w: cell,
        h: cell,
        fill: colors[TONE_KEY[tone]],
      });
    }
  }
  return rects;
}

/**
 * Builds the complete scene for one avatar. Pure: same configuration in, byte-identical
 * scene out.
 */
export function avatarScene(config: AvatarConfig, options: { title?: string } = {}): PixelScene {
  const colors = AVATAR_COLORS[config.palette];
  const rects = [
    ...backgroundRects(config, colors),
    ...characterSpriteRects({
      character: config.character,
      expression: config.expression,
      accessory: config.accessory,
      colors,
      originX: 0,
      originY: 0,
      cell: AVATAR_CELL,
    }),
  ];

  return {
    width: AVATAR_SIZE,
    height: AVATAR_SIZE,
    title: options.title ?? describeAvatar(config),
    rects,
    texts: [],
  };
}

/** The accessible name. Plain English assembled from enum values only. */
export function describeAvatar(config: AvatarConfig): string {
  const accessory = config.accessory === "none" ? "no accessory" : `a ${config.accessory}`;
  return `Pixel-art ${config.character} agent avatar in the ${config.palette} palette, with ${accessory} and a ${config.expression} expression, on a ${config.background} background.`;
}

/** The public URL that serves this agent's avatar. */
export function avatarUrlFor(username: string, version = 1): string {
  return `/api/public/agent-avatar/${encodeURIComponent(username)}.svg?v=${version}`;
}
